resume-positioning.code:
VERBS = {"cut", "reduced", "shipped", "built", "led", "designed", "migrated"}

BULLETS = [
    "Worked on search infrastructure and helped with performance",
    "Cut p99 search latency 4.1s to 900ms (-78%), load-test report + PR linked",
    "Passionate team player with strong communication skills",
    "Migrated 14 services to the new auth gateway, zero rollbacks, memo linked",
    "Improved database performance significantly",
]

MARKERS = ["PR", "report", "dashboard", "repo", "memo"]


def score_bullet(text):
    missing = []
    first = text.split()[0].lower() if text.split() else ""
    if first not in VERBS:
        missing.append("verb")
    if not any(ch.isdigit() for ch in text):
        missing.append("number")
    if not any(m in text for m in MARKERS):
        missing.append("artifact")
    return 3 - len(missing), missing


def pct_reduction(old, new):
    return round((old - new) / old * 100)


for b in BULLETS:
    score, missing = score_bullet(b)
    tag = "KEEP" if score == 3 else "REWRITE"
    lack = ','.join(missing) if missing else 'none'
    print(f"[{score}/3] {tag} missing={lack} :: {b[:46]}")
print(f"honest improvement: {pct_reduction(4.1, 0.9)}% reduction")
print(f"resume-lie version would claim: {round((4.1 - 0.9) / 0.9 * 100)}%")

behavioral-story-bank.code:
COMPETENCIES = [
    "conflict", "failure", "ambiguity", "leadership",
    "delivery-under-pressure", "data-driven-decisions",
]

STORIES = {
    "ttl-disagreement": {
        "covers": {"conflict", "data-driven-decisions", "leadership",
                    "delivery-under-pressure"},
        "has_number": True, "has_artifact": True,
    },
    "retry-storm-incident": {
        "covers": {"delivery-under-pressure"},
        "has_number": True, "has_artifact": True,
    },
    "search-migration": {
        "covers": {"ambiguity"},
        "has_number": False, "has_artifact": True,
    },
}


def coverage(stories, competencies):
    covered = set()
    for s in stories.values():
        covered |= s["covers"]
    uncovered = [c for c in competencies if c not in covered]
    overloaded = sorted(
        ((name, len(s["covers"])) for name, s in stories.items()),
        key=lambda x: (-x[1], x[0]),
    )[0]
    unquantified = sorted(
        name for name, s in stories.items()
        if not (s["has_number"] and s["has_artifact"])
    )
    return uncovered, overloaded, unquantified


uncovered, overloaded, unquantified = coverage(STORIES, COMPETENCIES)
print(f"uncovered competencies: {', '.join(uncovered)}")
print(f"overloaded story: {overloaded[0]} carries {overloaded[1]} competencies")
print(f"stories not proof-grade: {', '.join(unquantified)}")
print(f"bank verdict: {len(uncovered)} gaps to fill before the loop")

coding-interview-loop.code:
PLAN = [
    ("clarify", 5), ("plan", 8), ("code", 20), ("test", 8), ("walkthrough", 4),
]
ACTUAL_A = [4, 7, 19, 9, 5]
ACTUAL_B = [1, 2, 38, 6, 3]
LIMIT = 45


def run_budget(plan, actual, limit=LIMIT):
    rows = []
    skipped = []
    clock = 0
    squeezed_first = None
    for (phase, planned), want in zip(plan, actual):
        if clock >= limit:
            granted = 0
        else:
            granted = min(want, limit - clock)
        clock += granted
        rows.append((phase, planned, granted))
        if granted == 0:
            skipped.append(phase)
        if squeezed_first is None and granted < planned / 2:
            squeezed_first = phase
    if not skipped and squeezed_first is None:
        verdict = "complete"
    else:
        verdict = f"squeezed: {squeezed_first or skipped[0]}"
    return rows, skipped, verdict


for name, actual in (("A", ACTUAL_A), ("B", ACTUAL_B)):
    rows, skipped, verdict = run_budget(PLAN, actual)
    spent_total = sum(s for _, _, s in rows)
    print(f"round {name}: {spent_total} min used, verdict: {verdict}")
    for phase, planned, spent in rows:
        mark = "SKIPPED" if spent == 0 else ("cut" if spent < planned / 2 else "ok")
        print(f"  {phase}: planned {planned}, got {spent} ({mark})")
